}

export function loginHandler(auth: AuthService): Handler {
  return async (req) => {
    const { email, password } = readCredentials(req.body);
    if (!email || !password) return json(400, { error: 'missing_credentials' });
    const result = await auth.login(email, password);
    if (!result.ok) return json(401, { error: result.reason });
    return json(200, { token: result.token, expiresAt: result.expiresAt });
  };
}

function readCredentials(body: unknown): { email?: string; password?: string } {
  if (typeof body !== 'object' || body === null) return {};
  const { email, password } = body as Record<string, unknown>;
  return {
    email: typeof email === 'string' ? email : undefined,
    password: typeof password === 'string' ? password : undefined,
  };
}

function bearerToken(req: HttpRequest): string {
  const header = req.headers['authorization'] ?? '';
  return header.startsWith('Bearer ') ? header.slice('Bearer '.length) : '';
}

export function logoutHandler(auth: AuthService): Handler {
  return async (req) => (auth.logout(bearerToken(req)) ? json(204, null) : json(401, { error: 'not_signed_in' }));
}

export function meHandler(auth: AuthService): Handler {
  return async (req) => {
    const user = auth.validate(bearerToken(req));
    if (!user) return json(401, { error: 'not_signed_in' });
    return json(200, { id: user.id, email: user.email, displayName: user.displayName });
  };
}

create(userId: string, now: number = Date.now()): Session {
  const id = randomUUID();
  const session: Session = { id, userId, token: signToken(id, this.secret), expiresAt: now + this.ttlMs };
  this.sessions.set(id, session);
  return session;
}

findByToken(token: string, now: number = Date.now()): Session | null {
  const id = verifyToken(token, this.secret);
  if (!id) return null;
  const session = this.sessions.get(id);
  if (!session || session.expiresAt <= now) return null;
  return session;
}

revoke(token: string): boolean {
  const session = this.findByToken(token);
  return session ? this.sessions.delete(session.id) : false;
}

